__d(function(e,t,o,n,a,r,i){a.exports={"fortunes.1.text":"I tuoi generatori vibrano di potere antico.","fortunes.1.label":"+5% CPS per 10 min","fortunes.2.text":"Gli spiriti della fabbrica ti sorridono.","fortunes.2.label":"+3% CPS per 15 min","fortunes.3.text":"Un ingranaggio dorato gira a tuo favore.","fortunes.3.label":"+10% CPS per 5 min","fortunes.4.text":"Il nastro trasportatore del destino scorre verso di te.","fortunes.4.label":"+4% CPS per 10 min","fortunes.5.text":"La fortuna favorisce gli operosi.","fortunes.5.label":"+7% CPS per 7 min","fortunes.6.text":"Gli dei della fabbrica annuiscono con approvazione.","fortunes.6.label":"+2% CPS per 20 min","fortunes.7.text":"Le tue macchine sussurrano segreti di efficienza.","fortunes.7.label":"+8% CPS per 6 min","fortunes.8.text":"Una lega rara infonde la tua linea di produzione.","fortunes.8.label":"+6% CPS per 8 min","fortunes.9.text":"Il turno di notte lavora il doppio stasera.","fortunes.9.label":"+15% CPS per 3 min","fortunes.10.text":"Un ingegnere misterioso regola la tua fabbrica.","fortunes.10.label":"+4% CPS per 12 min","fortunes.11.text":"Le tue dita formicolano di potere.","fortunes.11.label":"+10% Potenza Clic per 10 min","fortunes.12.text":"Il tocco del destino \xe8 su di te.","fortunes.12.label":"+5% Potenza Clic per 15 min","fortunes.13.text":"La tua mano che clicca si sente inarrestabile.","fortunes.13.label":"+15% Potenza Clic per 5 min","fortunes.14.text":"Il tuono scorre attraverso le tue dita.","fortunes.14.label":"+8% Potenza Clic per 8 min","fortunes.15.text":"Una scarica di adrenalina affina i tuoi tap.","fortunes.15.label":"+20% Potenza Clic per 3 min","fortunes.16.text":"La ruota della fortuna ti chiama.","fortunes.16.label":"+1 Giro Gratis","fortunes.17.text":"La fortuna ha girato a tuo favore... letteralmente.","fortunes.17.label":"+1 Giro Gratis","fortunes.18.text":"Un biglietto dorato cade dal biscotto.","fortunes.18.label":"+2 Giri Gratis","fortunes.19.text":"Un piccione atterra sulla tua fabbrica. Non succede nulla.","fortunes.19.label":"Niente","fortunes.20.text":"Senti un rombo lontano. Era solo il tuo stomaco.","fortunes.20.label":"Niente","fortunes.21.text":"Il biscotto era stantio. Ma comunque delizioso.","fortunes.21.label":"Niente","fortunes.22.text":"Un operaio ti saluta. Tu ricambi. Fine.","fortunes.22.label":"Niente","fortunes.23.text":"Trovi un biglietto: 'Riprova pi\xf9 tardi.' Classico.","fortunes.23.label":"Niente","fortunes.24.text":"L'universo alza le spalle.","fortunes.24.label":"Niente","fortunes.25.text":"Apri il biscotto. \xc8 vuoto. Poetico.","fortunes.25.label":"Niente","fortunes.26.text":"Un manager prova a dire qualcosa, poi dimentica.","fortunes.26.label":"Niente","fortunes.27.text":"Il biscotto si sbriciola. Nel nulla.","fortunes.27.label":"Niente","fortunes.28.text":"404: Fortuna non trovata.","fortunes.28.label":"Niente","fortunes.29.text":"Questa fortuna \xe8 stata lasciata intenzionalmente vuota.","fortunes.29.label":"Niente","fortunes.30.text":"Un gatto appare. Ti giudica in silenzio. Se ne va.","fortunes.30.label":"Niente","fortunes.31.text":"Un piccolo gremlin si \xe8 infiltrato nei tuoi generatori.","fortunes.31.label":"-2% CPS per 5 min","fortunes.32.text":"Mercurio \xe8 retrogrado. La tua fabbrica lo sente.","fortunes.32.label":"-1% CPS per 10 min","fortunes.33.text":"La macchina del caff\xe8 \xe8 rotta. Il morale cala.","fortunes.33.label":"-3% CPS per 3 min","fortunes.34.text":"Un gabbiano ruba un ingranaggio. La produzione singhiozza.","fortunes.34.label":"-2% CPS per 5 min","fortunes.35.text":"L'ispezione sulla sicurezza arriva senza preavviso.","fortunes.35.label":"-5% CPS per 2 min","fortunes.36.text":"Il tuo miglior operaio si \xe8 dato malato. Allergico agli straordinari.","fortunes.36.label":"-1% CPS per 8 min","fortunes.37.text":"Dietro ogni grande fabbrica c'\xe8 qualcuno che tocca il suo telefono.","fortunes.37.label":"Niente","fortunes.38.text":"Stai leggendo questa fortuna. Questa \xe8 la tua fortuna.","fortunes.38.label":"Niente","fortunes.39.text":"Il vero tesoro erano le monete spese lungo il cammino.","fortunes.39.label":"Niente","fortunes.40.text":"Aiuto, sono intrappolato in una fabbrica di biscotti della fortuna.","fortunes.40.label":"Niente","fortunes.41.text":"I tuoi numeri fortunati sono: tutti.","fortunes.41.label":"Niente","fortunes.42.text":"Questo biscotto \xe8 stato fatto con amore. E codice.","fortunes.42.label":"Niente","fortunes.43.text":"Ricorda: ogni moneta spesa qui \xe8 ben spesa.","fortunes.43.label":"Niente","fortunes.44.text":"Curiosit\xe0: hai appena pagato per questa fortuna. Ne \xe8 valsa la pena?","fortunes.44.label":"Niente","fortunes.45.text":"La tua fabbrica \xe8 orgogliosa di te. Continua cos\xec.","fortunes.45.label":"Niente","fortunes.46.text":"Oggi \xe8 un buon giorno per spendere pi\xf9 monete.","fortunes.46.label":"Niente"}},359,[]);
__d(function(e,t,n,r,a,s,l){a.exports={"fortunes.1.text":"Dina generatorer surrar av ur\xe5ldrig kraft.","fortunes.1.label":"+5% CPS i 10 min","fortunes.2.text":"Fabrikens andar ler mot dig.","fortunes.2.label":"+3% CPS i 15 min","fortunes.3.text":"Ett gyllene kugghjul v\xe4nder sig till din f\xf6rdel.","fortunes.3.label":"+10% CPS i 5 min","fortunes.4.text":"\xd6dets transportband fl\xf6dar \xe5t ditt h\xe5ll.","fortunes.4.label":"+4% CPS i 10 min","fortunes.5.text":"Lyckan gynnar de flitiga.","fortunes.5.label":"+7% CPS i 7 min","fortunes.6.text":"Fabriksgudarna nickar gillande.","fortunes.6.label":"+2% CPS i 20 min","fortunes.7.text":"Dina maskiner viskar hemligheter om effektivitet.","fortunes.7.label":"+8% CPS i 6 min","fortunes.8.text":"En s\xe4llsynt legering genomsyrar din produktionslinje.","fortunes.8.label":"+6% CPS i 8 min","fortunes.9.text":"Nattskiftet jobbar dubbelt ikv\xe4ll.","fortunes.9.label":"+15% CPS i 3 min","fortunes.10.text":"En mystisk ingenj\xf6r finjusterar din fabrik.","fortunes.10.label":"+4% CPS i 12 min","fortunes.11.text":"Dina fingrar pirrar av kraft.","fortunes.11.label":"+10% Klickkraft i 10 min","fortunes.12.text":"\xd6dets ber\xf6ring vilar \xf6ver dig.","fortunes.12.label":"+5% Klickkraft i 15 min","fortunes.13.text":"Din klickande hand k\xe4nns ostoppbar.","fortunes.13.label":"+15% Klickkraft i 5 min","fortunes.14.text":"\xc5ska fl\xf6dar genom dina fingertoppar.","fortunes.14.label":"+8% Klickkraft i 8 min","fortunes.15.text":"En adrenalinst\xf6t sk\xe4rper dina tryck.","fortunes.15.label":"+20% Klickkraft i 3 min","fortunes.16.text":"Lyckohjulet kallar p\xe5 dig.","fortunes.16.label":"+1 Gratissnurr","fortunes.17.text":"Lyckan har snurrat till din f\xf6rdel\u2026 bokstavligen.","fortunes.17.label":"+1 Gratissnurr","fortunes.18.text":"En gyllene biljett faller ur kakan.","fortunes.18.label":"+2 Gratissnurr","fortunes.19.text":"En duva landar p\xe5 din fabrik. Ingenting h\xe4nder.","fortunes.19.label":"Ingenting","fortunes.20.text":"Du h\xf6r ett avl\xe4gset muller. Det var bara din mage.","fortunes.20.label":"Ingenting","fortunes.21.text":"Kakan var gammal. Men fortfarande god.","fortunes.21.label":"Ingenting","fortunes.22.text":"En arbetare vinkar \xe5t dig. Du vinkar tillbaka. Det var allt.","fortunes.22.label":"Ingenting","fortunes.23.text":"Du hittar en lapp: 'F\xf6rs\xf6k igen senare.' Klassiker.","fortunes.23.label":"Ingenting","fortunes.24.text":"Universum rycker p\xe5 axlarna.","fortunes.24.label":"Ingenting","fortunes.25.text":"Du \xf6ppnar kakan. Den \xe4r tom. Poetiskt.","fortunes.25.label":"Ingenting","fortunes.26.text":"En chef f\xf6rs\xf6ker s\xe4ga n\xe5got, gl\xf6mmer sedan.","fortunes.26.label":"Ingenting","fortunes.27.text":"Kakan smulas s\xf6nder. Till intet.","fortunes.27.label":"Ingenting","fortunes.28.text":"404: Sp\xe5dom hittades inte.","fortunes.28.label":"Ingenting","fortunes.29.text":"Denna sp\xe5dom l\xe4mnades avsiktligt tom.","fortunes.29.label":"Ingenting","fortunes.30.text":"En katt dyker upp. D\xf6mer dig tyst. G\xe5r.","fortunes.30.label":"Ingenting","fortunes.31.text":"En liten gremlin sm\xf6g sig in i dina generatorer.","fortunes.31.label":"-2% CPS i 5 min","fortunes.32.text":"Merkurius \xe4r retrograd. Din fabrik k\xe4nner det.","fortunes.32.label":"-1% CPS i 10 min","fortunes.33.text":"Kaffemaskinen \xe4r trasig. Moralen sjunker.","fortunes.33.label":"-3% CPS i 3 min","fortunes.34.text":"En m\xe5s stj\xe4l ett kugghjul. Produktionen hickar.","fortunes.34.label":"-2% CPS i 5 min","fortunes.35.text":"Arbetsmilj\xf6inspektionen dyker upp.","fortunes.35.label":"-5% CPS i 2 min","fortunes.36.text":"Din b\xe4sta arbetare sjukskrev sig. Allergisk mot \xf6vertid.","fortunes.36.label":"-1% CPS i 8 min","fortunes.37.text":"Bakom varje stor fabrik finns n\xe5gon som petar p\xe5 sin telefon.","fortunes.37.label":"Ingenting","fortunes.38.text":"Du l\xe4ser denna sp\xe5dom. Det \xe4r din sp\xe5dom.","fortunes.38.label":"Ingenting","fortunes.39.text":"Den verkliga skatten var mynten du spenderade p\xe5 v\xe4gen.","fortunes.39.label":"Ingenting","fortunes.40.text":"Hj\xe4lp, jag \xe4r fast i en lyckokaksfabrik.","fortunes.40.label":"Ingenting","fortunes.41.text":"Dina lyckosiffror \xe4r: alla.","fortunes.41.label":"Ingenting","fortunes.42.text":"Denna kaka bakades med k\xe4rlek. Och kod.","fortunes.42.label":"Ingenting","fortunes.43.text":"Kom ih\xe5g: varje mynt du spenderar h\xe4r \xe4r v\xe4l spenderat.","fortunes.43.label":"Ingenting","fortunes.44.text":"Kul fakta: du betalade just f\xf6r denna sp\xe5dom. V\xe4rt det?","fortunes.44.label":"Ingenting","fortunes.45.text":"Din fabrik \xe4r stolt \xf6ver dig. Forts\xe4tt.","fortunes.45.label":"Ingenting","fortunes.46.text":"Idag \xe4r en bra dag att spendera fler mynt.","fortunes.46.label":"Ingenting"}},360,[]);
